function r(e){const t=(e??0)/100;return new Intl.NumberFormat("en-IN",{style:"currency",currency:"INR",maximumFractionDigits:2}).format(t)}function a(e){if(!e)return"—";const t=new Date(e.length===10?`${e}T00:00:00`:e);return Number.isNaN(t.getTime())?e:t.toLocaleDateString("en-IN",{day:"2-digit",month:"short",year:"numeric"})}function n(e){switch(e){case"PAID":case"CAPTURED":case"ACCEPTED":case"ACTIVE":case"DONE":return"bg-emerald-50 text-emerald-700 ring-emerald-200";case"OVERDUE":case"FAILED":case"EXPIRED":case"VOID":return"bg-rose-50 text-rose-700 ring-rose-200";case"PARTIALLY_PAID":case"SENT":case"ISSUED":case"PENDING":return"bg-amber-50 text-amber-700 ring-amber-200";case"CANCELLED":case"REFUNDED":return"bg-slate-100 text-slate-600 ring-slate-200";default:return"bg-indigo-50 text-indigo-700 ring-indigo-200"}}function s(e){return e.replace(/_/g," ").toLowerCase().replace(/\b\w/g,t=>t.toUpperCase())}export{n as a,r as i,a as s,s as t};
